def count_blocking_findings(pip_audit_path, bandit_path):
    blocking = 0
    for dep in json.load(open(pip_audit_path))["dependencies"]:
        for vuln in dep.get("vulns", []):
            if vuln["severity"].upper() in {"CRITICAL", "HIGH"}:
                blocking += 1
    for result in json.load(open(bandit_path))["results"]:
        if result["issue_severity"] == "HIGH":
            blocking += 1
    return blocking
